from alpaca.data import requests as dr
from alpaca.trading.client import TradingClient
from alpaca.trading import requests as tr
from alpaca.trading import enums as te
print('alpaca', getattr(alpaca, '__version__', None))
for cls in [StockHistoricalDataClient, OptionHistoricalDataClient, TradingClient]:
 print('\n', cls.__name__)
 for n in dir(cls):
  if any(s in n.lower() for s in ('active','mover','snapshot','option','asset','contract','order','position')) and not n.startswith('_'):
   try: print(n, inspect.signature(getattr(cls,n)))
   except: print(n)
print('\nData requests')
for n in dir(dr):
 if any(s in n.lower() for s in ('snapshot','option','active','mover')):
  o=getattr(dr,n)
  try: print(n, inspect.signature(o))
  except: print(n)
print('\nTrading requests/enums')
for mod in [tr,te]:
 for n in dir(mod):
  if any(s in n.lower() for s in ('asset','option','orderclass','timeinforce')):
   o=getattr(mod,n)
   try: print(n, inspect.signature(o))
   except: print(n, o)
